import {CIRCUIT,rpc,decodeBytes} from './tapeout.mjs';
import {riskCircuitDraft} from './risk-circuit.mjs';
const word=n=>BigInt(n).toString(16).padStart(64,'0');
export const refEvalData=(id,n)=>{if(!Number.isSafeInteger(id)||id<1||!Number.isInteger(n)||n<0||n>7)throw Error('REF_INPUT_INVALID');return '0x934d06ea'+word(id)+word(64)+word(1)+n.toString(16).padStart(2,'0')+'00'.repeat(31);};
export async function readRefCircuit(id,{block,read=rpc}={}){if(!Number.isSafeInteger(id)||id<1||id===48)throw Error('REF_ID_INVALID');if(Number(await read('eth_chainId',[]))!==196)throw Error('WRONG_CHAIN');block??=await read('eth_blockNumber',[]);if(!/^0x[0-9a-f]+$/i.test(block))throw Error('INVALID_BLOCK');const call=data=>read('eth_call',[{to:CIRCUIT.address,data},block]);const [info,owner,netlistRaw]=await Promise.all([call('0x084d60f1'+word(id)),call('0x6352211e'+word(id)),call('0x3fc4be56'+word(id))]);if(!/^0x[0-9a-f]{256}$/i.test(info)||!/^0x[0-9a-f]{64}$/i.test(owner))throw Error('REF_METADATA_INVALID');const shape=info.slice(2).match(/.{64}/g).map(x=>Number(BigInt('0x'+x))),netlist=decodeBytes(netlistRaw);if(shape.join(',')!=='3,1,0,12'||netlist!==riskCircuitDraft().netlist||('0x'+owner.slice(-40)).toLowerCase()!==CIRCUIT.author)throw Error('REF_DESIGN_MISMATCH');const blockNumber=Number(BigInt(block)),cases=await Promise.all(Array.from({length:8},async(_,n)=>{const calldata=refEvalData(id,n),rawResult=await call(calldata),out=decodeBytes(rawResult),expected=n===7?1:0;if(out!==(expected?'0x01':'0x00'))throw Error('REF_LOGIC_MISMATCH');return {R:n&1,C:(n>>1)&1,D:(n>>2)&1,OUT0:expected,chainId:196,contract:CIRCUIT.address,circuitId:id,blockNumber,method:'eth_call',calldata,rawResult};}));return {schema:'moneylab-deployed-ref-proof.v1',chainId:196,contract:CIRCUIT.address,circuitId:id,tapeId:id+'.2.167',owner:CIRCUIT.author,blockNumber,shape,netlist,cases,checkedAt:new Date().toISOString()};}
export async function activeRefProof(block){const response=await fetch('/api/ref/config',{cache:'no-store'});if(!response.ok)throw Error('REF_CONFIG_UNAVAILABLE');const config=await response.json();return config.active?readRefCircuit(config.circuitId,{block}):null;}
export function nativePolicyResult(signals,proof){const r=proof?.cases?.find(r=>r.R===signals.reserve&&r.C===signals.coverage&&r.D===signals.installments);if(!r)throw Error('REF_RECEIPT_MISSING');return {schema:'moneylab-native-policy.v1',output:r.OUT0,receipt:r,circuitId:proof.circuitId,blockNumber:proof.blockNumber,scope:'R/C/D combination executed by the deployed REF circuit. Money Lab supplies the comparison bits; this does not attest financial inputs or whole-game execution.'};}
